#!/bin/bash
# Decode campaigns of the fictitious F10 model (generated by systems/f10/generate_f10.py from the final checkpoint
# H122000) for varying context lengths. Every entry of CONTEXTS is "tokens:kv_precision".
# Every run starts only when the one-minute load average is below LOAD_THRESHOLD, after PAUSE seconds.
# The output folder keeps its archived name (results/campagne_20261127/f10_contesto).
set -u
cd "$(dirname "$0")"
OUT=${OUT:-../results/campagne_20261127/f10_contesto}; mkdir -p "$OUT"
PY=${PY:-../../.venv-systems/bin/python}; THRESHOLD=${LOAD_THRESHOLD:-${SOGLIA_CARICO:-1.5}}; PAUSE=${PAUSE:-${PAUSA:-30}}
CONTEXTS=${CONTEXTS:-${CONTESTI:-"128:fp32 512:fp32 2000:fp32 8000:fp32"}}; REPS=${REPS:-${RIP:-3}}
for r in $(seq 1 $REPS); do for entry in $CONTEXTS; do
  L=${entry%%:*}; KV=${entry##*:}
  sleep $PAUSE
  while :; do c=$(sysctl -n vm.loadavg | awk '{print $2}'); awk -v c=$c -v s=$THRESHOLD 'BEGIN{exit !(c<s)}' && break; sleep 10; done
  echo "$(date +%T) contesto $L kv $KV ripetizione $r carico $c swap $(sysctl -n vm.swapusage | awk '{print $6}')" | tee -a "$OUT/condizioni.txt"
  STERA_WEIGHTS=H122000 $PY f10_context.py --context $L --kv $KV --out "$OUT/f10_L${L}_${KV}_r${r}.json" > "$OUT/f10_L${L}_${KV}_r${r}.log" 2>&1
done; done
echo FINE | tee -a "$OUT/condizioni.txt"
